_swapPairList[sender] &&
block.number < startTradeBlock + killBatchBlockNumber
) {
if (block.number != user2blocks[tx.origin]) {
user2blocks[tx.origin] = block.number;
} else {
batchBots++;
_funTransfer(sender, recipient, amount);
return;
}
}
}
